//! 🧪️ Same canonical typed Fault streams into original native pages with independent physical receipts.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,close_original_retained_step};
fn clock()->Option<u64>{Some(0)}
use semio_framework_diagnostic::Fault;
use semio_framework_value::FromValue;
fn observed<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);assert!(!heap.overflowed);(value,(heap.requested_bytes,heap.released_bytes))}
fn physical(progress:RetainedCloneProgress,heap:(usize,usize),grant:RetainedCloneGrant){assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap)}
#[test]
fn original_typed_fault_publication_streams_canonical_wire_without_truncation_and_preserves_native_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let p=law["originalGrant"].as_array().unwrap();let extent=law["bufferExtent"].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize};
 let source_policy:serde_json::Value=serde_json::from_str(include_str!("../../../../⚠️failure/🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(source_policy["stock"].clone()).unwrap();
 let canonical:serde_json::Value=serde_json::from_str(include_str!("../../../../../⚠️diagnostic/🧪️tests/🧫️fixtures/🧯️fault/🔣️.json")).unwrap();let mut rows=canonical["cases"].as_array().unwrap().clone();let mut long=rows[1].clone();long["id"]=serde_json::json!("original-long-window");long["input"]["message"]=serde_json::json!("🧩\\\"\n".repeat(2049));long["expected"]["message"]=long["input"]["message"].clone();rows.push(long);
 for row in &rows{let fault=Fault::from_value(serde_json::from_value(row["input"].clone()).unwrap()).unwrap();let foreign=Fault::from_value(serde_json::from_value(row["input"].clone()).unwrap()).unwrap();let fault_pointer=std::ptr::addr_of!(fault);let text_pointer=fault.message.as_ptr();
  for cut in [0,1,257,usize::MAX]{
   let operation=OperationId(99733);let generation=Generation(17);let(mut caller,heap)=observed(||OriginalJobFixtureCaller::admit(operation,generation,stock,clock,source_policy["deadlineUs"].as_u64().unwrap(),source_policy["fuel"].as_u64().unwrap()));let mut born=heap.0;let mut released=heap.1;
   let(mut publication,heap)=observed(RetainedFaultPublication::new);assert_eq!(heap,(0,0));let original_header=std::ptr::addr_of!(publication);let window_pointer=publication.buffer.as_ptr();let mut turns=0;let mut copied=0;let mut descriptor=None;
   while descriptor.is_none()&&turns<cut{
    let demand=caller.turn(grant,|cx|{let(demand,heap)=observed(||publication.advance_demands(&fault,cx).unwrap());assert_eq!(heap,(0,0));Ok(demand)}).unwrap();
    if publication.wire.is_complete()&&publication.wire.buffered_bytes(&publication.buffer).unwrap().is_empty()&&publication.builder.published().is_some(){let bytes=std::mem::size_of::<Option<JobOutcomeDescriptor>>();let denied=RetainedCloneGrant{maximum_copy_bytes:bytes-1,..grant};caller.turn(denied,|cx|{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(value,heap)=observed(||publication.advance_from_fault_with_cursor(&fault,cx,bytes).unwrap().map(JobOutcomeBorrow::into_descriptor));assert!(value.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);Ok(())}).unwrap();}
    for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant}),(demand.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:0,..grant}),(demand.depth>0).then(||RetainedCloneGrant{maximum_depth:demand.depth-1,..grant})].into_iter().flatten(){caller.turn(denied,|cx|{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(value,heap)=observed(||publication.advance_from_fault(&fault,cx).unwrap().map(JobOutcomeBorrow::into_descriptor));assert!(value.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);Ok(())}).unwrap();}
    if publication.binding.is_some(){caller.turn(grant,|cx|{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(value,heap)=observed(||publication.advance_from_fault(&foreign,cx).map(|value|value.map(JobOutcomeBorrow::into_descriptor)));assert!(value.is_err());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);Ok(())}).unwrap();}
    let payload_frontier={let buffered=publication.wire.buffered_bytes(&publication.buffer).unwrap().len();if publication.binding.is_none()||!publication.builder.is_initialized()||publication.delivered{false}else if buffered==publication.buffer.len()||publication.wire.is_complete()&&buffered>0{publication.flush_cursor<buffered}else{!publication.wire.is_complete()}};
    let(value,heap)=observed(||caller.turn(grant,|cx|publication.advance_from_fault(&fault,cx).map(|value|value.map(JobOutcomeBorrow::into_descriptor))));let value=value.unwrap();let progress=caller.receipt();physical(progress,heap,grant);assert_eq!(progress.copied_items,1);if payload_frontier{assert!(progress.copied_bytes<=extent);copied+=progress.copied_bytes}else{assert_eq!(progress.copied_bytes,demand.copy_bytes)}born+=heap.0;released+=heap.1;descriptor=value;turns+=1;assert!(turns<100000);assert_eq!(std::ptr::addr_of!(publication),original_header);assert_eq!(publication.buffer.as_ptr(),window_pointer);assert_eq!(std::ptr::addr_of!(fault),fault_pointer);assert_eq!(fault.message.as_ptr(),text_pointer);
   }
   if let Some(mut descriptor)=descriptor{let(view,heap)=observed(||publication.borrow_outcome(&descriptor).unwrap());assert_eq!(heap,(0,0));let payload=match view{JobOutcomeView::Fault{detail,..}=>detail,_=>panic!("same canonical Fault view required")};let native_payload=payload as*const _;assert_eq!(publication.published().unwrap()as*const _,native_payload);let mut bytes=Vec::with_capacity(payload.len());for index in 0..payload.page_count(){bytes.extend_from_slice(payload.page(index).unwrap());}assert_eq!(serde_json::from_slice::<serde_json::Value>(&bytes).unwrap(),row["expected"]);assert_eq!(copied,bytes.len()*2);let(step,heap)=observed(||descriptor.acknowledge(RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());assert!(!descriptor.is_acknowledged());let(result,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..grant},|cx|{let step=descriptor.acknowledge(cx.retained_grant());cx.consume_fuel(1);cx.consume_retained(step.progress())?;Ok(step)}));let step=result.unwrap();assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(descriptor.is_acknowledged());let(_,heap)=observed(||drop(descriptor));assert_eq!(heap,(0,0));}
   while !publication.terminal_is_empty(){let(demand,heap)=observed(||publication.retirement_demands().unwrap());assert_eq!(heap,(0,0));for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}),(demand.depth>0).then(||RetainedCloneGrant{maximum_depth:demand.depth-1,..grant})].into_iter().flatten(){let(turn,heap)=observed(||publication.close_step(denied));assert_eq!(turn.work,law["closeCpu"]["denied"].as_u64().unwrap());let step=turn.result.unwrap();assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());}let mut work=0;let(result,heap)=observed(||caller.turn(grant,|cx|cx.with_original_retirement(|same|close_original_retained_step(same,demand,|actual|{let turn=publication.close_step(actual);work=turn.work;turn}))));let step=result.unwrap();assert_eq!(work,law["closeCpu"]["admitted"].as_u64().unwrap());physical(step.progress(),heap,grant);born+=heap.0;released+=heap.1;}
   let(turn,heap)=observed(||publication.close_step(grant));assert_eq!(turn.work,law["closeCpu"]["cached"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));let(_,heap)=observed(||drop(publication));assert_eq!(heap,(0,0));let(_,heap)=observed(||caller.retire(stock));born+=heap.0;released+=heap.1;assert_eq!(born,released);assert_eq!(std::ptr::addr_of!(fault),fault_pointer);assert_eq!(fault.message.as_ptr(),text_pointer);
  }
 }
}


#[test]
fn cancelled_original_fault_uses_only_authenticated_bounded_retirement(){
 let source:serde_json::Value=serde_json::from_str(include_str!("../../../../⚠️failure/🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(source["stock"].clone()).unwrap();let cases:serde_json::Value=serde_json::from_str(include_str!("../../../../../⚠️diagnostic/🧪️tests/🧫️fixtures/🧯️fault/🔣️.json")).unwrap();let fault=Fault::from_value(serde_json::from_value(cases["cases"][0]["input"].clone()).unwrap()).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(99801),Generation(9),stock,clock,source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let mut publication=RetainedFaultPublication::new();let mut descriptor=None;caller.cancel().cancel_now();
 caller.turn(stock,|cx|{assert!(OriginalFaultPayloadStep::borrow_fault(cx,&fault).is_err());Ok(())}).unwrap();
 for _ in 0..4096{if descriptor.is_some(){break}descriptor=caller.turn(stock,|cx|cx.with_original_retirement(|cx|publication.advance_from_fault_with_cursor(&fault,cx,std::mem::size_of::<Option<JobOutcomeDescriptor>>()).map(|loan|loan.map(JobOutcomeBorrow::into_descriptor)))).unwrap();}let mut descriptor=descriptor.expect("bounded cleanup publishes the retained original fault");assert!(matches!(publication.borrow_outcome(&descriptor).unwrap(),JobOutcomeView::Fault{..}));
 caller.turn(stock,|cx|{assert!(JobOutcomeBorrow::admit_fault_with_cursor_retiring(cx,publication.published().unwrap(),0).is_err());Ok(())}).unwrap();
 let nonfault=RetainedJobPayload::empty(JobPayloadStream::CommitOutput);caller.turn(stock,|cx|cx.with_original_retirement(|cx|{assert!(JobOutcomeBorrow::admit_fault_with_cursor_retiring(cx,&nonfault,0).is_err());Ok(())})).unwrap();drop(nonfault);
 caller.turn(stock,|cx|cx.with_original_retirement(|cx|{let step=descriptor.acknowledge(cx.retained_grant());cx.consume_retained(step.progress())?;cx.consume_fuel(1);Ok(())})).unwrap();assert!(descriptor.is_acknowledged());drop(descriptor);
 for _ in 0..4096{if publication.terminal_is_empty(){break}let demand=publication.retirement_demands().unwrap();caller.turn(stock,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,demand,|grant|publication.close_step(grant)))).unwrap();}assert!(publication.terminal_is_empty());drop(publication);caller.retire(stock);
}
